'use server'

import { cookies } from 'next/headers'
import { refresh } from 'next/cache'

const NOTIFICATIONS_COOKIE = 'notifications-enabled'

export async function toggleNotifications() {
  const cookieStore = await cookies()
  const current = cookieStore.get(NOTIFICATIONS_COOKIE)?.value === 'true'
  const next = !current

  cookieStore.set(NOTIFICATIONS_COOKIE, String(next), {
    httpOnly: true,
    path: '/',
    sameSite: 'lax',
    maxAge: 60 * 60 * 24 * 365,
  })

  refresh()
}

import { cookies } from 'next/headers'
import { toggleNotifications } from '@/app/actions'

export default async function Home() {
  const cookieStore = await cookies()
  const notificationsEnabled =
    cookieStore.get('notifications-enabled')?.value === 'true'

  return (
    <main>
      <h1>Settings</h1>
      <form action={toggleNotifications}>
        <p>Notifications are currently {notificationsEnabled ? 'ON' : 'OFF'}</p>
        <button type="submit">
          Turn notifications {notificationsEnabled ? 'OFF' : 'ON'}
        </button>
      </form>
    </main>
  )
}

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode
}>) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  )
}
